#include "../charge_compiler/json.hpp"
#include <unordered_map>
#include <unordered_set>
#include <iostream>
#include <time.h>
using I=long long;
static double now(){timespec t{};require(clock_gettime(CLOCK_BOOTTIME,&t)==0,"clock");return t.tv_sec+t.tv_nsec*1e-9;}
int main(int argc,char**argv){try{
 require(argc==2,"usage: map_native_device_basis CONFIG");auto cfg=Json::read(argv[1]);double deadline=cfg.at("deadline_uptime").num();
 std::unordered_map<std::string,std::string> groups;auto selected=Json::read(cfg.at("selected_groups").str());for(auto& row:selected.at("selected_groups").arr())require(groups.emplace(std::to_string(row.at("group").integer()),row.at("original").str()).second,"unique selected device group");selected=Json();
 std::unordered_map<std::string,I> global;std::ifstream runtime(cfg.at("R_nodes").str());require(bool(runtime),"runtime R node input");std::string line;I prior=0;while(std::getline(runtime,line)){require(now()<deadline,"device runtime map deadline");auto row=Json::parse(line);I id=row.at(0).integer();require(id==prior+1,"contiguous runtime R node IDs");require(global.emplace(row.at(1).str(),id).second,"unique runtime R names");prior=id;}require(runtime.eof(),"complete runtime R map");
 auto raw=Json::read(cfg.at("bindings").str());Json::Array bindings;std::unordered_set<std::string> wanted;I discarded=0;
 for(auto& row:raw.arr()){auto found=groups.find(row.at("native_group_id").str());if(found==groups.end()){discarded++;continue;}require(found->second==row.at("original_conductor").str(),"selected device conductor identity");I terminal=row.at("terminal").integer();require(terminal>=1&&terminal<=4,"native device terminal enum");wanted.insert(row.at("private_id").str());bindings.push_back(std::move(row));}raw=Json();
 std::unordered_map<std::string,Json> nodes;raw=Json::read(cfg.at("nodes").str());for(auto& row:raw.arr()){auto name=row.at("private_id").str();if(wanted.count(name)){require(groups.at(row.at("native_group_id").str())==row.at("original_conductor").str(),"device private node conductor");require(nodes.emplace(name,std::move(row)).second,"unique selected private device node");}}raw=Json();require(nodes.size()==wanted.size(),"all final binding private nodes exist");
 I mapped=0,requires_R_only=0;std::unordered_set<std::string> mapped_nodes,missing_nodes;std::unordered_map<std::string,I> models,terminals;
 std::ofstream out(cfg.at("output").str());require(bool(out),"device basis mapping output");for(auto& binding:bindings){require(now()<deadline,"device basis mapping deadline");auto name=binding.at("private_id").str();auto& node=nodes.at(name);require(node.at("native_group_id").str()==binding.at("native_group_id").str()&&node.at("original_conductor").str()==binding.at("original_conductor").str(),"exact device private identity");auto found=global.find(name);binding["printed_native_node"]=node.at("printed_name");binding["native_node_point_internal"]=node.at("point_internal");binding["device_location_is_terminal_geometry"]=false;
  if(found==global.end()){binding["basis_binding_state"]="requires_R_only_voltage_union";requires_R_only++;missing_nodes.insert(name);}else{binding["basis_binding_state"]="exact_existing_spatial_voltage";binding["global_voltage_id"]=found->second;mapped++;mapped_nodes.insert(name);}models[binding.at("model").str()]++;terminals[std::to_string(binding.at("terminal").integer())]++;out<<binding.dump()<<'\n';}out.close();require(bool(out),"device basis mapping close");
 Json report=Json::object();report["selected_native_groups"]=I(groups.size());report["selected_binding_records"]=I(bindings.size());report["superseded_binding_records_retained_in_source"]=discarded;report["exact_existing_spatial_voltage_bindings"]=mapped;report["requires_R_only_voltage_union_bindings"]=requires_R_only;report["unique_existing_spatial_voltage_nodes"]=I(mapped_nodes.size());report["unique_R_only_voltage_nodes"]=I(missing_nodes.size());Json mm=Json::object(),tt=Json::object();for(auto&[k,v]:models)mm[k]=v;for(auto&[k,v]:terminals)tt[k]=v;report["model_binding_counts"]=mm;report["native_terminal_enum_counts"]=tt;report["physical_device_binding_qualified"]=false;report["runtime_model_eligible"]=false;report["release_qualified"]=false;std::cout<<report.dump()<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
